package com.companion.ai.worldmemory;
import com.companion.ai.*; import com.companion.ai.json.LlmJsonObjectExtractor; import com.companion.ai.prompt.*; import com.companion.entity.enums.WorldMemoryType; import com.fasterxml.jackson.databind.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; import java.util.*;
@Component @RequiredArgsConstructor public class LlmWorldMemoryExtractor { private final LlmClient client; private final ObjectMapper mapper; private final PromptTemplateLoader loader; private final PromptTemplateRenderer renderer;
 public List<WorldMemoryCandidate> extract(WorldMemoryExtractionContext c){try{String s=renderer.render(loader.load(PromptTemplateKey.WORLD_MEMORY_SYSTEM),Map.of());String u=renderer.render(loader.load(PromptTemplateKey.WORLD_MEMORY_USER),Map.of("worldSnapshot",bound(c.worldSnapshot()),"participantSnapshots",bound(c.participantSnapshots()),"transcript",bound(c.transcript()),"existingMemory",bound(c.existingMemory())));JsonNode a=mapper.readTree(LlmJsonObjectExtractor.extract(client.complete(s,u,1000).content())).path("memories");if(!a.isArray())return List.of();List<WorldMemoryCandidate> out=new ArrayList<>();for(JsonNode n:a){if(out.size()==5)break;try{WorldMemoryType t=WorldMemoryType.valueOf(n.path("type").asText());String k=n.path("key").isTextual()?n.path("key").asText().trim():null;String content=n.path("content").asText().trim();int importance=n.path("importance").asInt(50);if(content.isEmpty()||content.length()>2000||(k!=null&&k.length()>255)||importance<1||importance>100)continue;out.add(new WorldMemoryCandidate(t,k,content,importance));}catch(Exception ignored){}}return out;}catch(Exception e){return List.of();}}
 private String bound(String s){if(s==null)return "";return s.substring(0,Math.min(12000,s.length()));}
}
